import React, { useMemo, useState } from 'react';
import {
  Home,
  CalendarDays,
  LayoutGrid,
  Trophy,
  MessageSquareText,
  UserRound,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

function cx(...classes) {
  return classes.filter(Boolean).join(' ');
}

function NavItem({ active, icon: Icon, label, onClick }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cx(
        'group inline-flex items-center gap-1 sm:gap-1.5 md:gap-2 rounded-lg px-2 sm:px-2.5 md:px-3 py-1.5 sm:py-2 text-[10px] sm:text-[12px] md:text-[13px] font-medium transition',
        active ? 'text-[#ff7849]' : 'text-white/65 hover:text-white/90'
      )}
      aria-current={active ? 'page' : undefined}
    >
      <Icon className={cx('h-4 w-4 flex-shrink-0', active ? 'text-[#ff7849]' : 'text-white/55 group-hover:text-white/80')} />
      <span className="hidden sm:inline">{label}</span>
    </button>
  );
}

function NavDropdown({ icon: Icon, label, active, items }) {
  const navigate = useNavigate();
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="relative group">
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className={cx(
          'group inline-flex items-center gap-1 sm:gap-1.5 md:gap-2 rounded-lg px-2 sm:px-2.5 md:px-3 py-1.5 sm:py-2 text-[10px] sm:text-[12px] md:text-[13px] font-medium transition',
          active ? 'text-[#ff7849]' : 'text-white/65 hover:text-white/90'
        )}
      >
        <Icon className={cx('h-4 w-4 flex-shrink-0', active ? 'text-[#ff7849]' : 'text-white/55 group-hover:text-white/80')} />
        <span className="hidden sm:inline">{label}</span>
      </button>

      {isOpen && (
        <div className="absolute top-full left-0 mt-1 bg-[#2a2a2a] border border-white/10 rounded-lg shadow-lg py-1 min-w-[180px] z-50">
          {items.map((item) => (
            <button
              key={item.path}
              onClick={() => {
                navigate(item.path);
                setIsOpen(false);
              }}
              className="w-full text-left px-4 py-2.5 text-[12px] text-white/70 hover:text-white/90 hover:bg-white/[0.06] transition"
            >
              {item.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function StatCard({ label, value }) {
  return (
    <div className="rounded-lg border border-white/10 bg-white/[0.04] p-4 sm:p-5 md:p-6 text-center">
      <p className="text-[10px] sm:text-[11px] md:text-[12px] uppercase tracking-widest text-white/50 mb-2 sm:mb-3">
        {label}
      </p>
      <p className="text-[24px] sm:text-[28px] md:text-[32px] font-bold text-white/95">
        {value}
      </p>
    </div>
  );
}

function WorkoutBadge({ type }) {
  const colorMap = {
    pecho: 'bg-[#ff7849]/20 text-[#ff7849]',
    espalda: 'bg-blue-500/20 text-blue-400',
    pierna: 'bg-purple-500/20 text-purple-400',
    cardio: 'bg-red-500/20 text-red-400',
    hombros: 'bg-green-500/20 text-green-400',
    yoga: 'bg-cyan-500/20 text-cyan-400',
  };

  return (
    <span className={cx('inline-block px-2.5 py-1 rounded text-[10px] sm:text-[11px] font-semibold uppercase tracking-wide', colorMap[type.toLowerCase()] || 'bg-white/10 text-white/60')}>
      {type}
    </span>
  );
}

export default function Calendario() {
  const navigate = useNavigate();
  const [currentDate, setCurrentDate] = useState(new Date(2025, 0, 1)); // Enero 2025 como en el mockup

  // Datos de entrenamientos por día
  const workoutsByDay = useMemo(() => {
    return {
      3: ['Pecho'],
      5: ['Pierna'],
      6: ['Espalda'],
      8: ['Cardio'],
      10: ['Pecho'],
      12: ['Pierna'],
      13: ['Hombros'],
      17: ['Espalda'],
      19: ['Pierna'],
      20: ['Pecho'],
      22: ['Cardio'],
      23: ['Pierna'],
      24: ['Espalda'],
      25: ['Hombros'],
      27: ['Yoga'],
      30: ['Pecho'],
    };
  }, []);

  const getDaysInMonth = (date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (date) => {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  };

  const previousMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1));
  };

  const daysInMonth = getDaysInMonth(currentDate);
  const firstDay = getFirstDayOfMonth(currentDate);
  const adjustedFirstDay = firstDay === 0 ? 6 : firstDay - 1; // Ajustar para que lunes sea 0

  const monthName = currentDate.toLocaleDateString('es-ES', { month: 'long' }).toUpperCase();
  const year = currentDate.getFullYear();

  // Contar entrenamientos totales (simulado)
  const totalWorkouts = 203;
  const monthWorkouts = Object.keys(workoutsByDay).length;

  const days = [];
  for (let i = 0; i < adjustedFirstDay; i++) {
    days.push(null);
  }
  for (let i = 1; i <= daysInMonth; i++) {
    days.push(i);
  }

  const weeks = [];
  for (let i = 0; i < days.length; i += 7) {
    weeks.push(days.slice(i, i + 7));
  }

  return (
    <div className="min-h-screen bg-[#1e1e1e] text-[#f5f5f5]">
      {/* Header */}
      <div className="h-[56px] sm:h-[64px] border-b border-white/10 sticky top-0 z-50 bg-[#1e1e1e]">
        <div className="flex h-full w-full items-center justify-between px-3 sm:px-4 md:px-6 lg:px-8">
          <div
            className="text-[18px] sm:text-[22px] font-bold tracking-wide text-[#ff7849]"
            style={{ fontFamily: 'Arimo, Poppins, system-ui' }}
          >
            FitTrack
          </div>

          <nav className="hidden items-center gap-1 sm:gap-2 md:flex">
            <NavItem icon={Home} label="Inicio" onClick={() => navigate('/dashboard')} />
            <NavDropdown
              active
              icon={CalendarDays}
              label="Calendario"
              items={[
                { label: 'Calendario', path: '/calendario' },
                { label: 'Historial de entrenamientos', path: '/entrenamientos' },
              ]}
            />
            <NavItem icon={LayoutGrid} label="FitGram" onClick={() => {}} />
            <NavItem icon={Trophy} label="Logros" onClick={() => {}} />
            <NavItem icon={MessageSquareText} label="Chat IA" onClick={() => {}} />
          </nav>

          <button
            type="button"
            onClick={() => {}}
            className="inline-flex items-center gap-2 rounded-lg bg-white/10 px-3 sm:px-4 py-1.5 sm:py-2 text-[12px] sm:text-[14px] font-medium text-white/90 transition hover:bg-white/15"
          >
            <UserRound className="h-4 w-4" />
            <span className="hidden sm:inline">Perfil</span>
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="w-full px-3 sm:px-4 md:px-6 lg:px-8 py-4 sm:py-5 md:py-6 lg:py-7 xl:py-8">
        <div className="max-w-6xl mx-auto space-y-5 sm:space-y-6 md:space-y-7">
          {/* Stats */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 sm:gap-4 md:gap-5">
            <StatCard label="Días entrenados en total" value={totalWorkouts} />
            <div className="flex items-center justify-center">
              <button
                onClick={previousMonth}
                className="p-2 hover:bg-white/10 rounded-lg transition"
              >
                <ChevronLeft className="h-5 w-5" />
              </button>
              <div className="text-[20px] sm:text-[24px] md:text-[28px] font-bold tracking-widest text-white/95 min-w-[180px] text-center">
                {monthName}
              </div>
              <button
                onClick={nextMonth}
                className="p-2 hover:bg-white/10 rounded-lg transition"
              >
                <ChevronRight className="h-5 w-5" />
              </button>
            </div>
            <StatCard label="Días entrenados este mes" value={monthWorkouts} />
          </div>

          {/* Calendar */}
          <div className="rounded-lg border border-white/10 bg-white/[0.04] overflow-hidden">
            {/* Days of week header */}
            <div className="grid grid-cols-7 border-b border-white/10 bg-white/[0.03]">
              {['LUN', 'MAR', 'MIE', 'JUE', 'VIE', 'SAB', 'DOM'].map((day) => (
                <div
                  key={day}
                  className="p-3 sm:p-4 text-center text-[11px] sm:text-[12px] md:text-[13px] font-bold uppercase tracking-wider text-white/50 border-r border-white/10 last:border-r-0"
                >
                  {day}
                </div>
              ))}
            </div>

            {/* Calendar grid */}
            <div className="divide-y divide-white/10">
              {weeks.map((week, weekIdx) => (
                <div key={weekIdx} className="grid grid-cols-7">
                  {week.map((day, dayIdx) => (
                    <div
                      key={`${weekIdx}-${dayIdx}`}
                      className={cx(
                        'aspect-square p-2 sm:p-3 md:p-4 border-r border-white/10 last:border-r-0 flex flex-col',
                        day ? 'bg-white/[0.02] hover:bg-white/[0.06] transition cursor-pointer' : 'bg-black/20'
                      )}
                    >
                      {day && (
                        <>
                          <div className="text-[11px] sm:text-[12px] md:text-[13px] font-semibold text-white/60 mb-1 sm:mb-1.5">
                            {day}
                          </div>
                          {workoutsByDay[day] && (
                            <div className="space-y-1 flex-1 flex flex-col justify-center">
                              {workoutsByDay[day].map((workout, idx) => (
                                <WorkoutBadge key={idx} type={workout} />
                              ))}
                            </div>
                          )}
                        </>
                      )}
                    </div>
                  ))}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
